import heapq


class Solution:
    def minSideJumps(self, obstacles):
        n = len(obstacles) - 1
        dist = [[float('inf')] * 3 for _ in range(n + 1)]
        dist[0][1] = 0
        pq = [(0, 0, 1)]
        while pq:
            d, i, l = heapq.heappop(pq)
            if d > dist[i][l]:
                continue
            if i == n:
                return d
            if obstacles[i + 1] != l + 1 and d < dist[i + 1][l]:
                dist[i + 1][l] = d
                heapq.heappush(pq, (d, i + 1, l))
            for tl in range(3):
                if tl != l and obstacles[i] != tl + 1 and d + 1 < dist[i][tl]:
                    dist[i][tl] = d + 1
                    heapq.heappush(pq, (d + 1, i, tl))
        return -1

