class Solution {
public:
    int minSideJumps(vector<int>& obstacles) {
        int n = obstacles.size() - 1;
        vector<array<int, 3>> dist(n + 1, {INT_MAX, INT_MAX, INT_MAX});
        priority_queue<array<int, 3>, vector<array<int, 3>>, greater<array<int, 3>>> pq;
        dist[0][1] = 0;
        pq.push({0, 0, 1});
        while (!pq.empty()) {
            auto [d, i, l] = pq.top();
            pq.pop();
            if (d > dist[i][l]) continue;
            if (i == n) return d;
            if (obstacles[i + 1] != l + 1 && d < dist[i + 1][l]) {
                dist[i + 1][l] = d;
                pq.push({d, i + 1, l});
            }
            for (int tl = 0; tl < 3; tl++) {
                if (tl != l && obstacles[i] != tl + 1 && d + 1 < dist[i][tl]) {
                    dist[i][tl] = d + 1;
                    pq.push({d + 1, i, tl});
                }
            }
        }
        return -1;
    }
};

