class Solution {
    public int minSideJumps(int[] obstacles) {
        int n = obstacles.length - 1;
        int[][] dist = new int[n + 1][3];
        for (int[] row : dist) Arrays.fill(row, Integer.MAX_VALUE);
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        dist[0][1] = 0;
        pq.offer(new int[]{0, 0, 1});
        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            int d = cur[0], i = cur[1], l = cur[2];
            if (d > dist[i][l]) continue;
            if (i == n) return d;
            if (obstacles[i + 1] != l + 1 && d < dist[i + 1][l]) {
                dist[i + 1][l] = d;
                pq.offer(new int[]{d, i + 1, l});
            }
            for (int tl = 0; tl < 3; tl++) {
                if (tl != l && obstacles[i] != tl + 1 && d + 1 < dist[i][tl]) {
                    dist[i][tl] = d + 1;
                    pq.offer(new int[]{d + 1, i, tl});
                }
            }
        }
        return -1;
    }
}

