var minSideJumps = function(obstacles) {
    const n = obstacles.length - 1;
    const dist = Array.from({length: n + 1}, () => [Infinity, Infinity, Infinity]);
    dist[0][1] = 0;
    const pq = [];
    const push = (item) => {
        pq.push(item);
        let i = pq.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (pq[p][0] <= pq[i][0]) break;
            [pq[p], pq[i]] = [pq[i], pq[p]];
            i = p;
        }
    };
    const pop = () => {
        const top = pq[0];
        const last = pq.pop();
        if (pq.length) {
            pq[0] = last;
            let i = 0;
            for (;;) {
                let s = i;
                const l = 2 * i + 1, r = 2 * i + 2;
                if (l < pq.length && pq[l][0] < pq[s][0]) s = l;
                if (r < pq.length && pq[r][0] < pq[s][0]) s = r;
                if (s === i) break;
                [pq[s], pq[i]] = [pq[i], pq[s]];
                i = s;
            }
        }
        return top;
    };
    push([0, 0, 1]);
    while (pq.length) {
        const [d, i, l] = pop();
        if (d > dist[i][l]) continue;
        if (i === n) return d;
        if (obstacles[i + 1] !== l + 1 && d < dist[i + 1][l]) {
            dist[i + 1][l] = d;
            push([d, i + 1, l]);
        }
        for (let tl = 0; tl < 3; tl++) {
            if (tl !== l && obstacles[i] !== tl + 1 && d + 1 < dist[i][tl]) {
                dist[i][tl] = d + 1;
                push([d + 1, i, tl]);
            }
        }
    }
    return -1;
};

