class Solution {
public:
    int minSideJumps(vector<int>& obstacles) {
        const int INF = INT_MAX / 2;
        int dp[3] = {1, 0, 1};
        for (int o : obstacles) {
            if (o) dp[o - 1] = INF;
            int best = min(dp[0], min(dp[1], dp[2]));
            for (int l = 0; l < 3; l++)
                if (l + 1 != o) dp[l] = min(dp[l], best + 1);
        }
        return min(dp[0], min(dp[1], dp[2]));
    }
};

