class Solution {
    public int minSideJumps(int[] obstacles) {
        final int INF = Integer.MAX_VALUE / 2;
        int[] dp = {1, 0, 1};
        for (int o : obstacles) {
            if (o > 0) dp[o - 1] = INF;
            int best = Math.min(dp[0], Math.min(dp[1], dp[2]));
            for (int l = 0; l < 3; l++)
                if (l + 1 != o) dp[l] = Math.min(dp[l], best + 1);
        }
        return Math.min(dp[0], Math.min(dp[1], dp[2]));
    }
}

